--[[
    MUZAN AVATAR EDIT  |  by NOX   (Delta / mobile version)
    Plays the edit as pictures + audio (no video player needed), and every
    Muzan shot is replaced by YOUR current avatar (current outfit).
    Everything is embedded in this script. First run unpacks it (loading bar).
]]

local FOLDER = "NOX_MUZAN_V6"
local VERSION = "v6-715"
local FPS = 24
local NFRAMES = 715
local DURATION = 29.9

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local StarterGui = game:GetService("StarterGui")
local TweenService = game:GetService("TweenService")
local lp = Players.LocalPlayer

local function notify(text)
	pcall(function()
		StarterGui:SetCore("SendNotification", {Title = "NOX EDIT", Text = text, Duration = 5})
	end)
end

pcall(function()
	local old = ((gethui and gethui()) or game:GetService("CoreGui")):FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)
pcall(function()
	local old = lp.PlayerGui:FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)

----------------------------------------------------------------
-- GUI
----------------------------------------------------------------
local gui = Instance.new("ScreenGui")
gui.Name = "NOXMuzanEdit"
gui.IgnoreGuiInset = true
gui.ResetOnSpawn = false
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
pcall(function()
	gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
end)
if not gui.Parent then
	gui.Parent = lp:WaitForChild("PlayerGui")
end

local closed, errored = false, false
local conn, sound

local back = Instance.new("Frame")
back.Size = UDim2.fromScale(1, 1)
back.BackgroundColor3 = Color3.new(0, 0, 0)
back.BorderSizePixel = 0
back.Parent = gui

local stage = Instance.new("Frame")
stage.AnchorPoint = Vector2.new(0.5, 0.5)
stage.Position = UDim2.fromScale(0.5, 0.5)
stage.Size = UDim2.fromScale(1, 1)
stage.BackgroundTransparency = 1
stage.ClipsDescendants = true
stage.Parent = back

local ratio = Instance.new("UIAspectRatioConstraint")
ratio.AspectRatio = 720 / 1280
ratio.AspectType = Enum.AspectType.FitWithinMaxSize
ratio.Parent = stage

-- header ("Real Owner Of This BGM" bar) from the original video
local header = Instance.new("ImageLabel")
header.Position = UDim2.fromScale(0, 200 / 1280)
header.Size = UDim2.fromScale(1, 112 / 1280)
header.BackgroundTransparency = 1
header.ZIndex = 1
header.Visible = true
header.Parent = stage

-- footage = the original video frames (pool of labels, see updateFootage)
local footage = Instance.new("Frame")
footage.Position = UDim2.fromScale(0, 372 / 1280)
footage.Size = UDim2.fromScale(1, 536 / 1280)
footage.BackgroundColor3 = Color3.new(0, 0, 0)
footage.BorderSizePixel = 0
footage.ClipsDescendants = true
footage.ZIndex = 1
footage.Visible = true
footage.Parent = stage

-- avatar layer, same rectangle as the footage
local band = Instance.new("Frame")
band.Position = footage.Position
band.Size = footage.Size
band.BackgroundTransparency = 1
band.ClipsDescendants = true
band.ZIndex = 5
band.Visible = false
band.Parent = stage

local holder = Instance.new("Frame")
holder.AnchorPoint = Vector2.new(0.5, 0.5)
holder.Position = UDim2.fromScale(0.5, 0.5)
holder.Size = UDim2.fromScale(1, 1)
holder.BackgroundColor3 = Color3.fromRGB(8, 28, 52)
holder.BorderSizePixel = 0
holder.ClipsDescendants = true
holder.ZIndex = 5
holder.Parent = band

local holderCorner = Instance.new("UICorner")
holderCorner.CornerRadius = UDim.new(0, 0)
holderCorner.Parent = holder

local grad = Instance.new("UIGradient")
grad.Color = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(4, 14, 30)),
	ColorSequenceKeypoint.new(0.5, Color3.fromRGB(18, 70, 120)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(6, 24, 46)),
})
grad.Parent = holder

local vp = Instance.new("ViewportFrame")
vp.Size = UDim2.fromScale(1, 1)
vp.BackgroundTransparency = 1
vp.Ambient = Color3.fromRGB(150, 170, 215)
vp.LightColor = Color3.fromRGB(210, 225, 255)
vp.LightDirection = Vector3.new(-0.4, -0.8, 0.5)
vp.ZIndex = 6
vp.Parent = holder

local cam = Instance.new("Camera")
cam.Parent = vp
vp.CurrentCamera = cam

----------------------------------------------------------------
-- LOADING SCREEN (gradient lives on a child frame, NOT on the
-- CanvasGroup, otherwise it tints/darkens all the text)
----------------------------------------------------------------
local loading = Instance.new("CanvasGroup")
loading.Size = UDim2.fromScale(1, 1)
loading.BackgroundTransparency = 1
loading.BorderSizePixel = 0
loading.ZIndex = 100
loading.Parent = gui

local lbg = Instance.new("Frame")
lbg.Size = UDim2.fromScale(1, 1)
lbg.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
lbg.BorderSizePixel = 0
lbg.ZIndex = 100
lbg.Parent = loading
local lgrad = Instance.new("UIGradient")
lgrad.Rotation = 90
lgrad.Color = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(3, 6, 14)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(10, 34, 62)),
})
lgrad.Parent = lbg

local function mkLabel(text, size, font, color, pos)
	local l = Instance.new("TextLabel")
	l.AnchorPoint = Vector2.new(0.5, 0.5)
	l.Position = pos
	l.Size = UDim2.new(0.9, 0, 0, size + 10)
	l.BackgroundTransparency = 1
	l.Text = text
	l.TextSize = size
	l.Font = font
	l.TextColor3 = color
	l.ZIndex = 101
	l.Parent = loading
	return l
end

local title = mkLabel("NOX", 54, Enum.Font.GothamBlack, Color3.fromRGB(255, 255, 255), UDim2.new(0.5, 0, 0.36, 0))
mkLabel("MUZAN AVATAR EDIT", 18, Enum.Font.GothamBold, Color3.fromRGB(90, 170, 255), UDim2.new(0.5, 0, 0.36, 44))

local track = Instance.new("Frame")
track.AnchorPoint = Vector2.new(0.5, 0.5)
track.Position = UDim2.new(0.5, 0, 0.55, 0)
track.Size = UDim2.new(0.6, 0, 0, 8)
track.BackgroundColor3 = Color3.fromRGB(25, 45, 75)
track.BorderSizePixel = 0
track.ZIndex = 101
track.Parent = loading
local tc = Instance.new("UICorner") tc.CornerRadius = UDim.new(1, 0) tc.Parent = track
local tsc = Instance.new("UISizeConstraint") tsc.MaxSize = Vector2.new(340, 8) tsc.Parent = track

local fill = Instance.new("Frame")
fill.Size = UDim2.fromScale(0, 1)
fill.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
fill.BorderSizePixel = 0
fill.ZIndex = 102
fill.Parent = track
local fc = Instance.new("UICorner") fc.CornerRadius = UDim.new(1, 0) fc.Parent = fill
local fg = Instance.new("UIGradient")
fg.Color = ColorSequence.new(Color3.fromRGB(40, 120, 230), Color3.fromRGB(150, 210, 255))
fg.Parent = fill

local status = mkLabel("Starting", 15, Enum.Font.Gotham, Color3.fromRGB(190, 210, 235), UDim2.new(0.5, 0, 0.55, 30))
local percent = mkLabel("0%", 14, Enum.Font.GothamBold, Color3.fromRGB(255, 255, 255), UDim2.new(0.5, 0, 0.55, 54))

local close = Instance.new("TextButton")
close.Size = UDim2.fromOffset(44, 44)
close.Position = UDim2.new(1, -50, 0, 6)
close.BackgroundTransparency = 1
close.Text = "X"
close.TextColor3 = Color3.fromRGB(255, 255, 255)
close.TextTransparency = 0.5
close.TextSize = 22
close.Font = Enum.Font.GothamBold
close.ZIndex = 300
close.Parent = gui

local stageText = "Starting"
local shownPct = 0
local function setProgress(p, text)
	if closed then return end
	p = math.clamp(p, 0, 1)
	if p < shownPct then p = shownPct end
	shownPct = p
	if text then stageText = text end
	TweenService:Create(fill, TweenInfo.new(0.25), {Size = UDim2.fromScale(p, 1)}):Play()
	percent.Text = math.floor(p * 100) .. "%"
end

task.spawn(function()
	local n = 0
	while not closed and not errored and loading.Parent do
		n += 1
		status.Text = stageText .. string.rep(".", n % 4)
		title.TextTransparency = 0.15 * (1 + math.sin(n * 0.8))
		task.wait(0.3)
	end
end)

local function cleanup()
	if closed then return end
	closed = true
	if conn then conn:Disconnect() end
	pcall(function() if sound then sound:Stop() sound:Destroy() end end)
	gui:Destroy()
end
close.MouseButton1Click:Connect(cleanup)

local function fail(msg)
	if closed then return end
	errored = true
	warn("[NOX EDIT] " .. tostring(msg))
	pcall(function()
		loading.Visible = true
		loading.GroupTransparency = 0
	end)
	title.TextTransparency = 0
	percent.Visible = false
	status.TextColor3 = Color3.fromRGB(255, 120, 120)
	status.TextWrapped = true
	status.TextSize = 14
	status.TextYAlignment = Enum.TextYAlignment.Top
	status.Position = UDim2.new(0.5, 0, 0.55, 90)
	status.Size = UDim2.new(0.9, 0, 0, 140)
	status.Text = "ERROR: " .. tostring(msg) .. "\n\n(screenshot this and send it to me)"
	notify("Error, check the screen")
	task.wait(30)
	cleanup()
end

