----------------------------------------------------------------
-- DECODER + FILE SETUP
----------------------------------------------------------------
local getasset = getcustomasset or getsynasset

local NATIVE
pcall(function()
	NATIVE = (crypt and crypt.base64decode) or (crypt and crypt.base64 and crypt.base64.decode)
		or base64_decode or (base64 and base64.decode) or (syn and syn.crypt and syn.crypt.base64.decode)
end)

local B64MAP = {}
do
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, #alphabet do B64MAP[alphabet:byte(i)] = i - 1 end
end

local function pureDecodeOne(s)
	local parts = {}
	local map = B64MAP
	for i = 1, #s, 4 do
		local a, b, c, d = s:byte(i, i + 3)
		local n = (map[a] or 0) * 262144 + (map[b] or 0) * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
		parts[#parts + 1] = string.char(math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256)
	end
	local res = table.concat(parts)
	local pad = 0
	if s:sub(-2) == "==" then pad = 2 elseif s:sub(-1) == "=" then pad = 1 end
	return res:sub(1, #res - pad)
end

local function isJpg(b) return b:byte(1) == 255 and b:byte(2) == 216 end
local function isMp3(b) return b:sub(1, 3) == "ID3" or b:byte(1) == 255 end

local function decodeOne(s, check)
	if NATIVE then
		local ok, res = pcall(NATIVE, s)
		if ok and type(res) == "string" and #res > 100 and check(res) then return res end
		NATIVE = nil -- native decoder is unreliable, use ours from now on
	end
	return pureDecodeOne(s)
end

local PATHS = {}
local function framePath(i)
	return FOLDER .. "/f_" .. string.format("%04d", i) .. ".jpg"
end

local function ensureAssets()
	if not (isfile and writefile and readfile and makefolder and isfolder and getasset) then
		error("Your executor is missing file functions (writefile / getcustomasset / makefolder)")
	end
	local good = false
	if isfolder(FOLDER) and isfile(FOLDER .. "/done.txt") then
		local ok, c = pcall(readfile, FOLDER .. "/done.txt")
		good = ok and c == VERSION
	end
	if not good then
		if not isfolder(FOLDER) then makefolder(FOLDER) end
		setProgress(0.16, "Unpacking edit (first run only)")
		writefile(FOLDER .. "/header.jpg", decodeOne(headerB64(), isJpg))
		writefile(FOLDER .. "/audio.mp3", decodeOne(audioB64(), isMp3))
		local idx = 0
		for _, group in ipairs(FRAME_GROUPS) do
			local D = group()
			for _, s in ipairs(D) do
				idx += 1
				writefile(framePath(idx), decodeOne(s, isJpg))
				if idx % 6 == 0 then
					setProgress(0.18 + (idx / NFRAMES) * 0.55, "Unpacking edit (first run only) " .. idx .. "/" .. NFRAMES)
					task.wait()
					if closed then return false end
				end
			end
		end
		if idx ~= NFRAMES then error("Unpack count mismatch (" .. idx .. ")") end
		writefile(FOLDER .. "/done.txt", VERSION)
	end
	return true
end

----------------------------------------------------------------
-- SHOTS
----------------------------------------------------------------
local V3, CF = Vector3.new, CFrame.lookAt

local shots = {
	{t0 = 0, t1 = 4, box = {pos = UDim2.fromScale(0.42, 0.36), size = UDim2.fromScale(0.22, 0.45)},
		cam = function(p) return CF(V3(0.5 - p, 3.6, -15), V3(0, 3, 0)), 32 end},
	{t0 = 4, t1 = 8, bob = true,
		cam = function(p) return CF(V3(-4.5 + p * 1.2, 0.9, -2 + p), V3(0, 0.5, -0.2)), 55 end},
	{t0 = 8, t1 = 10, bob = true,
		cam = function(p) return CF(V3(-6 + p * 2.5, 3, -8), V3(0, 3.2, 0)), 50 end},
	{t0 = 10, t1 = 13,
		cam = function(p) return CF(V3(0, 5.7, -4.6 + p * 1.6), V3(0, 5.5, 0)) * CFrame.Angles(0, 0, math.rad(-6 + p * 6)), 45 end},
	{t0 = 13, t1 = 15,
		cam = function(p) return CF(V3(0, 12, 6 - p), V3(0, 3, 0)), 50 end},
	{t0 = 15, t1 = 18, bob = true,
		cam = function(p) return CF(V3(2 - p, 1.6, 6), V3(0, 1.6, 0)), 55 end},
	{t0 = 18, t1 = 22, bob = true,
		cam = function(p) return CF(V3(-5, 0.6, -0.8 + p * 1.2), V3(0, 0.4, 0)), 55 end},
	{t0 = 22, t1 = 26, box = {pos = UDim2.fromScale(0.30, 0.44), size = UDim2.fromScale(0.20, 0.48)},
		cam = function(p) return CF(V3(0.5 - p * 0.5, 3.6, -15), V3(0, 3, 0)), 32 end},
	{t0 = 26, t1 = 99,
		cam = function(p, t)
			local push = math.clamp((t - 26) / 4, 0, 1)
			return CF(V3(0, 5, -6 + push * 1.6), V3(0, 4.7, 0)), 40
		end},
}

local current
local function applyShot(s)
	current = s
	if s.box then
		holder.Position = s.box.pos
		holder.Size = s.box.size
		holderCorner.CornerRadius = UDim.new(1, 0)
	else
		holder.Position = UDim2.fromScale(0.5, 0.5)
		holder.Size = UDim2.fromScale(1, 1)
		holderCorner.CornerRadius = UDim.new(0, 0)
	end
end

----------------------------------------------------------------
-- FOOTAGE PLAYER (rolling pool of image labels with look-ahead)
----------------------------------------------------------------
local K = 14
local pool, poolFrame = {}, {}
for k = 1, K do
	local l = Instance.new("ImageLabel")
	l.Size = UDim2.fromScale(1, 1)
	l.BackgroundColor3 = Color3.new(0, 0, 0)
	l.BorderSizePixel = 0
	l.ScaleType = Enum.ScaleType.Stretch
	l.ZIndex = 1
	l.Parent = footage
	pool[k] = l
end
local shownSlot
local useIsLoaded = true

local function assetFor(i)
	local a = PATHS[i]
	if not a then
		a = getasset(framePath(i))
		PATHS[i] = a
	end
	return a
end

local function ensureFrame(i)
	if i < 1 or i > NFRAMES then return end
	local k = (i - 1) % K + 1
	if poolFrame[k] ~= i then
		poolFrame[k] = i
		pool[k].Image = assetFor(i)
	end
end

local function updateFootage(t)
	local cur = math.clamp(math.floor(t * FPS) + 1, 1, NFRAMES)
	for i = cur, cur + K - 2 do ensureFrame(i) end
	-- show the newest frame (<= cur) that has finished loading
	for i = cur, math.max(1, cur - (K - 2)), -1 do
		local k = (i - 1) % K + 1
		if poolFrame[k] == i and ((not useIsLoaded) or pool[k].IsLoaded) then
			if k ~= shownSlot then
				if shownSlot then pool[shownSlot].ZIndex = 1 end
				pool[k].ZIndex = 3
				shownSlot = k
			end
			break
		end
	end
end

----------------------------------------------------------------
-- MAIN
----------------------------------------------------------------
local function step(name, fn)
	local ok, e = pcall(fn)
	if not ok then error("[" .. name .. "] " .. tostring(e), 0) end
end

local function main()
	-- 1) copy the executor's avatar (current outfit)
	setProgress(0.04, "Copying your avatar")
	local char = lp.Character or lp.CharacterAdded:Wait()
	char:WaitForChild("HumanoidRootPart")
	task.wait(0.2)
	local wasArchivable = char.Archivable
	char.Archivable = true
	local avatar = char:Clone()
	char.Archivable = wasArchivable
	if not avatar then error("Couldn't copy your avatar") end
	for _, d in ipairs(avatar:GetDescendants()) do
		if d:IsA("Script") or d:IsA("LocalScript") then d:Destroy() end
	end
	for _, d in ipairs(avatar:GetDescendants()) do
		if d:IsA("BasePart") then
			d.Anchored = true
			d.CanCollide = false
		end
	end
	local hum = avatar:FindFirstChildOfClass("Humanoid")
	if hum then hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end
	avatar.Parent = vp
	avatar:PivotTo(CFrame.new(0, 3, 0))
	setProgress(0.14, "Avatar ready")

	-- 2) unpack files (first run only)
	if not ensureAssets() then return end
	if closed then return end

	-- 3) header + audio + first frames
	setProgress(0.78, "Loading pictures")
	step("header", function() header.Image = getasset(FOLDER .. "/header.jpg") end)

	setProgress(0.82, "Loading audio")
	local audioOk = pcall(function()
		sound = Instance.new("Sound")
		sound.SoundId = getasset(FOLDER .. "/audio.mp3")
		sound.Volume = 1
		sound.Parent = gui
	end)
	if audioOk then
		local w = 0
		while sound and not sound.IsLoaded and w < 8 and not closed do
			task.wait(0.2)
			w += 0.2
		end
		if sound and not sound.IsLoaded then
			notify("Audio didn't load, playing without sound")
		end
	else
		notify("Audio unsupported, playing without sound")
	end

	setProgress(0.9, "Preparing frames")
	for i = 1, K - 2 do ensureFrame(i) end
	local w = 0
	while not pool[1].IsLoaded and w < 8 and not closed do
		task.wait(0.2)
		w += 0.2
	end
	if closed then return end
	if not pool[1].IsLoaded then
		-- try forcing a preload, some executors don't update IsLoaded
		pcall(function() game:GetService("ContentProvider"):PreloadAsync({pool[1], pool[2], pool[3]}) end)
		task.wait(0.5)
	end
	if not pool[1].IsLoaded then
		-- don't give up: IsLoaded may simply not work here. Show frames by time instead.
		useIsLoaded = false
		notify("Picture check unsupported, starting anyway")
	end

	-- 4) ready: start the edit
	setProgress(1, "Ready")
	task.wait(0.5)
	step("first shot", function() applyShot(shots[1]) end)
	header.Visible = true
	footage.Visible = true
	band.Visible = true

	local t0 = os.clock()
	if sound then pcall(function() sound.TimePosition = 0 sound:Play() end) end

	pcall(function()
		TweenService:Create(loading, TweenInfo.new(0.6), {GroupTransparency = 1}):Play()
	end)
	task.delay(0.7, function()
		if not errored and loading.Parent then loading:Destroy() end
	end)

	local dbg = Instance.new("TextLabel")
	dbg.Size = UDim2.new(1, 0, 0, 40)
	dbg.Position = UDim2.new(0, 0, 1, -40)
	dbg.BackgroundTransparency = 1
	dbg.TextColor3 = Color3.fromRGB(255, 90, 90)
	dbg.TextSize = 12
	dbg.TextWrapped = true
	dbg.Font = Enum.Font.Gotham
	dbg.Text = ""
	dbg.ZIndex = 400
	dbg.Parent = gui

	local finishing = false
	local lastErr
	local function frame()
		local t
		if sound and sound.IsPlaying and sound.TimeLength > 0 then
			t = sound.TimePosition
		else
			t = os.clock() - t0
		end

		if t >= DURATION and not finishing then
			finishing = true
			task.delay(0.6, cleanup)
		end

		updateFootage(t)

		local shot = shots[#shots]
		for _, s in ipairs(shots) do
			if t >= s.t0 and t < s.t1 then
				shot = s
				break
			end
		end
		if shot ~= current then applyShot(shot) end

		local p = math.clamp((t - shot.t0) / (shot.t1 - shot.t0), 0, 1)
		local cf, fov = shot.cam(p, t)
		cam.CFrame = cf
		cam.FieldOfView = fov

		local bob = shot.bob and math.abs(math.sin(t * 7)) * 0.18 or 0
		avatar:PivotTo(CFrame.new(0, 3 + bob, 0))
		grad.Rotation = (t * 25) % 360
	end

	conn = RunService.RenderStepped:Connect(function()
		local ok, e = pcall(frame)
		if not ok and e ~= lastErr then
			lastErr = e
			dbg.Text = "frame error: " .. tostring(e)
			warn("[NOX EDIT] frame error: " .. tostring(e))
		end
	end)
end

task.spawn(function()
	local ok, err = pcall(main)
	if not ok then fail(tostring(err)) end
end)
